"""
Text Adventure Engine

This module provides a text-based adventure game engine supporting rooms, items, inventory management, command parsing,
and saving/loading game state via JSON.
"""

import json
import os

class AdventureGame:
    def __init__(self, config_file='config.json'):
        """Initialize the game with config from a JSON file."""
        self.load_config(config_file)
        self.current_room = 'entrance'
        self.inventory = []

    def load_config(self, filename):
        """Load rooms and items configuration from JSON file."""
        with open(filename, 'r') as f:
            data = json.load(f)
        self.rooms = data.get('rooms', {})
        self.items = data.get('items', {})

    def describe_room(self):
        """Return the description of the current room and its contents."""
        room = self.rooms[self.current_room]
        desc = room['description'] + '\n'
        if room['items']:
            desc += 'You see: ' + ', '.join(room['items']) + '\n'
        desc += 'Exits: ' + ', '.join(room['exits'].keys())
        return desc

    def move(self, direction):
        """Move to a different room if an exit exists in that direction."""
        room = self.rooms[self.current_room]
        if direction in room['exits']:
            self.current_room = room['exits'][direction]
            return f'You move {direction} to {self.current_room}.'
        else:
            return 'You can\'t go that way.'

    def get_item(self, item_name):
        """Pick up an item from the current room, if portable."""
        room = self.rooms[self.current_room]
        if item_name in room['items']:
            if self.items.get(item_name, {}).get('portable', False):
                room['items'].remove(item_name)
                self.inventory.append(item_name)
                return f'You picked up the {item_name}.'
            else:
                return f'The {item_name} cannot be picked up.'
        else:
            return f'There is no {item_name} here.'

    def drop_item(self, item_name):
        """Drop an item from inventory into the current room."""
        if item_name in self.inventory:
            self.inventory.remove(item_name)
            self.rooms[self.current_room]['items'].append(item_name)
            return f'You dropped the {item_name}.'
        else:
            return f'You don\'t have a {item_name}.'

    def inventory_list(self):
        """List items currently in inventory."""
        if self.inventory:
            return 'You have: ' + ', '.join(self.inventory)
        else:
            return 'Your inventory is empty.'

    def save_game(self, filename='savegame.json'):
        """Save the current game state to a JSON file."""
        state = {
            'current_room': self.current_room,
            'inventory': self.inventory,
            'rooms': self.rooms
        }
        with open(filename, 'w') as f:
            json.dump(state, f, indent=2)
        return f'Game saved to {filename}.'

    def load_game(self, filename='savegame.json'):
        """Load game state from a JSON file."""
        if not os.path.exists(filename):
            return f'No save file {filename} found.'
        with open(filename, 'r') as f:
            state = json.load(f)
        self.current_room = state.get('current_room', 'entrance')
        self.inventory = state.get('inventory', [])
        self.rooms = state.get('rooms', self.rooms)
        return f'Game loaded from {filename}.'

    def parse_command(self, command):
        """Parse a two-word command and execute it.
        Supported commands: go <direction>, get <item>, drop <item>, look, inventory, save, load, quit
        """
        command = command.strip().lower()
        if command == 'look':
            return self.describe_room()
        if command == 'inventory':
            return self.inventory_list()
        if command == 'save':
            return self.save_game()
        if command == 'load':
            return self.load_game()
        if command == 'quit':
            return 'quit'

        parts = command.split()
        if len(parts) != 2:
            return 'Invalid command. Use two-word commands like "go north" or "get sword".'

        verb, noun = parts
        if verb == 'go':
            return self.move(noun)
        if verb == 'get':
            return self.get_item(noun)
        if verb == 'drop':
            return self.drop_item(noun)

        return 'Unknown command.'


if __name__ == '__main__':
    game = AdventureGame('/work/config.json')
    print('Welcome to the Adventure Game!')
    while True:
        print('\n' + game.describe_room())
        command = input('> ')
        result = game.parse_command(command)
        if result == 'quit':
            print('Thanks for playing!')
            break
        else:
            print(result)
